def compact_with_index(t):
    indices=[i for i,c in enumerate(t) if not c.isspace() and c not in '\x07\x08\u200c\ufeff']
    return ''.join(t[i] for i in indices),indices

data={};docs={};standards={}
for v,pp in [(1,[14,46,64,102,122,140]),(2,[14,36,70,98,128])]:
    data[v]=json.loads((BASE/f'jihaksa/IS{v}/activities.json').read_text(encoding='utf8'))
    docs[v]=fitz.open(data[v]['metadata']['source_file'])
    for p in pp:
        t=docs[v][p-1].get_text(); start=t.index('[10통과'); t=t[start:t.index('1/',start)]
        for m in re.finditer(r'\[(10통과[12]-\d\d-\d\d)\]([^\[]+)',t):
            quote=re.sub('[\x07\x08\u200c]','',m.group(0)).strip()
            standards[m.group(1)]={'code':m.group(1),'book_id':f'jihaksa_IS{v}','pdf_page':p,'quote':quote}

out=[];missing=[]
for line in ROWS.strip().splitlines():
    v,n,cs,q,why,note=line.split('|');v=int(v);n=int(n)
    record=data[v]['data'][n-1]
    assert record['id']==f'jihaksa_is{v}_{n:04d}'
    pages=list(record['source']['pdf_pages'])
    if v==1 and n==16:pages.append(73)
    found=[];evidencepages=[]
    for query in q.split(' ~~~ '):
        needle=compact_with_index(query)[0]
        matched=False
        for p in pages:
            raw=docs[v][p-1].get_text().split('\n'+str(p)+'\n')[0]
            hay,idx=compact_with_index(raw);pos=hay.find(needle)
            if pos>=0:
                found.append(raw[idx[pos]:idx[pos+len(needle)-1]+1].strip());evidencepages.append(p);matched=True;break
        if not matched:missing.append((v,n,query))
    codes=[f'10통과{v}-{code}' for code in cs.split(',') if code]
    out.append({'record_id':record['id'],'codes':codes,'method':'content_alignment' if codes else 'unresolved','rationale':why,'activity_evidence':{'pdf_pages':sorted(set(evidencepages)),'quote':'\n[…]\n'.join(found)},'standard_evidence':[standards[c] for c in codes],'review_note':note or None})
if missing:
    print('UNMATCHED',json.dumps(missing,ensure_ascii=False,indent=2));raise SystemExit(1)
assert len(out)==81
assert len(standards)==31
result={'publisher':'지학사','mappings':out}
(BASE/'achievement_mapping/jihaksa.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
from collections import Counter
print(Counter(x['method'] for x in out))
print('records',len(out),'codes',len(standards),'all quotes verified against student text')
